import fs from 'node:fs/promises';
import { chromium } from 'playwright';

const BASE='https://www.statesideqm.com';
const THEME='158561894555';
const NAME=process.env.SQ_ROUTE_NAME||'Accessories';
const ROUTE=process.env.SQ_ROUTE||'/collections/accessories-gifts-collectibles';
const EXPECT_FIX=process.env.SQ_ROUTE_FIX||'accessories-gifts-collectibles';
const FALSE_HANDLES=new Set((process.env.SQ_FALSE_HANDLES||'all,stateside-quartermaster-logo-merch,air-national-guard-series,state-guard-series,rotc-series,jrotc-series,military-schools-academies,public-safety-series,army-national-guard-series').split(',').filter(Boolean));
const out='cert-v3-route';
const delay=ms=>new Promise(r=>setTimeout(r,ms));
function target(extra={}){const u=new URL(ROUTE,BASE);u.searchParams.set('preview_theme_id',THEME);for(const[k,v]of Object.entries(extra))u.searchParams.set(k,String(v));return u.toString()}
async function nav(page,u){let last;for(let i=0;i<4;i++){try{const r=await page.goto(u,{waitUntil:'domcontentloaded',timeout:40000});const s=r?.status()||0;if(s===200){await delay(900);return s}last=new Error('HTTP '+s);if(![429,500,502,503,504].includes(s))break}catch(e){last=e}await delay(1800*(i+1))}throw last||new Error('navigation failed')}
async function waitReady(page){await page.waitForFunction((expect)=>{const m=document.querySelector('#MainContent');if(m?.dataset.sqRefineV3Error)return true;return m?.dataset.sqRefineV3Ready==='true'&&(!expect||m?.dataset.sqRefineV3RouteFix===expect)},EXPECT_FIX,{timeout:45000});const err=await page.locator('#MainContent').getAttribute('data-sq-refine-v3-error');if(err)throw new Error('V3 '+err)}
async function inspect(page){return page.evaluate((falseHandles)=>{const visible=el=>{if(!el)return false;const s=getComputedStyle(el),r=el.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity||1)!==0&&r.width>0&&r.height>0};const h=raw=>{try{const m=new URL(raw,location.origin).pathname.match(/^\/collections\/([^/?#]+)/);return m?decodeURIComponent(m[1]):''}catch{return''}};const main=document.querySelector('#MainContent'),side=main?.querySelector('.sq-refine-v3-sidebar'),size=main?.querySelector('.sq-refine-v3-page-size'),grid=main?.querySelector('.product-grid'),groups=side?[...side.querySelectorAll('.sq-refine-v3-group')]:[],structural=side?[...side.querySelectorAll('input[data-kind="structural"]')].map(i=>({label:i.closest('label')?.innerText.trim()||'',target:i.dataset.target||'',handle:h(i.dataset.target||'')})):[],native=side?[...side.querySelectorAll('input[data-kind="native"]')].map(i=>i.dataset.filterName||''):[],sizes=size?[...size.querySelectorAll('input')].map(i=>({value:i.value,checked:i.checked})):[],cards=grid?[...grid.querySelectorAll(':scope>.product-grid__item')].filter(x=>x.querySelector('a[href*="/products/"]')).length:0,cols=grid?getComputedStyle(grid).gridTemplateColumns.split(' ').filter(Boolean).length:0,ss=side?getComputedStyle(side):null,sr=side?.getBoundingClientRect(),hiddenInside=main?[...main.querySelectorAll('[data-sq-refine-v3-hidden-nav="true"]')].filter(visible).length:0,hiddenOutside=[...document.querySelectorAll('[data-sq-refine-v3-hidden-nav="true"]')].filter(x=>!main?.contains(x)&&visible(x)).length;return{ready:main?.dataset.sqRefineV3Ready||'',routeFix:main?.dataset.sqRefineV3RouteFix||'',sidebarVisible:visible(side),title:side?.querySelector('.sq-refine-v3-sidebar__title')?.textContent.trim()||'',pageSizeVisible:visible(size),pageSizeInsideSidebar:!!size?.closest('.sq-refine-v3-sidebar'),sizes,groups:groups.map(g=>({label:g.querySelector(':scope>summary')?.textContent.trim()||'',open:g.open,checked:g.querySelectorAll('input:checked').length,inputs:g.querySelectorAll('input[type="checkbox"]').length})),structural,native,falseStructural:structural.filter(x=>falseHandles.includes(x.handle)),gridVisible:visible(grid),columns:cols,cards,sidebarPosition:ss?.position||'',sidebarHeight:sr?.height||0,hiddenInside,hiddenOutside};},[...FALSE_HANDLES])}
async function toggle(page){const d=page.locator('.sq-refine-v3-sidebar .sq-refine-v3-group:not([open])').first();if(!await d.count())return{pass:true,reason:'no inactive group'};const s=d.locator(':scope>summary');await s.scrollIntoViewIfNeeded();const before=await s.evaluate(el=>getComputedStyle(el,'::after').content);let click1='',click2='';try{await s.click({timeout:7000})}catch(e){click1=String(e)}await delay(150);const opened=await d.getAttribute('open')!==null;const after=await s.evaluate(el=>getComputedStyle(el,'::after').content);try{await s.click({timeout:7000})}catch(e){click2=String(e)}await delay(150);const closed=await d.getAttribute('open')===null;const final=await s.evaluate(el=>getComputedStyle(el,'::after').content);return{pass:/\+/.test(before)&&opened&&/[−\u2212-]/.test(after)&&closed&&/\+/.test(final)&&!click1&&!click2,before,after,final,opened,closed,click1,click2}}
function errs(d,t,mobile=false){const e=[];if(d.ready!=='true')e.push('V3 not ready');if(d.routeFix!==EXPECT_FIX)e.push('route fix marker missing');if(!d.sidebarVisible)e.push('sidebar hidden');if(d.title!=='Refine Products')e.push('bad title');if(!d.pageSizeVisible||d.pageSizeInsideSidebar)e.push('bad page-size placement');if(d.sizes.map(x=>x.value).join(',')!=='50,100,250'||!d.sizes.find(x=>x.value==='50')?.checked)e.push('bad page-size options/default');if(!d.groups.length)e.push('no refine groups');for(const g of d.groups){if(!g.inputs)e.push('empty group '+g.label);if(!g.checked&&g.open)e.push('inactive group open '+g.label);if(g.checked&&!g.open)e.push('active group closed '+g.label)}if(d.groups.some(g=>/color\s*[\/&+]\s*pattern|color and pattern/i.test(g.label)))e.push('combined Color/Pattern');if(d.falseStructural.length)e.push('unrelated structural links: '+d.falseStructural.map(x=>x.handle).join(','));if(d.hiddenInside||d.hiddenOutside)e.push(`old navigation visible inside=${d.hiddenInside} outside=${d.hiddenOutside}`);if(!d.gridVisible)e.push('product grid hidden');if(d.gridVisible&&d.columns!==(mobile?2:3))e.push(`${mobile?'mobile':'desktop'} columns=${d.columns}`);if(mobile){if(d.sidebarPosition==='sticky')e.push('mobile sidebar sticky')}else{if(d.sidebarPosition!=='sticky')e.push('sidebar not sticky');if(d.sidebarHeight<600)e.push('sidebar too short')}if(!d.cards)e.push('no product cards');if(d.native.some(n=>!n.startsWith('filter.')))e.push('bad native filter');if(!t.pass)e.push('plus/minus toggle failed '+JSON.stringify(t));return e}
await fs.mkdir(out,{recursive:true});
const browser=await chromium.launch({headless:true});
const report={name:NAME,route:ROUTE,desktop:{},mobile:{},pass:false};
const dctx=await browser.newContext({viewport:{width:1440,height:1000}}),dp=await dctx.newPage();
try{report.desktop.http=await nav(dp,target());await waitReady(dp);report.desktop.data=await inspect(dp);report.desktop.toggle=await toggle(dp);report.desktop.errors=errs(report.desktop.data,report.desktop.toggle,false);await dp.screenshot({path:`${out}/desktop.png`,fullPage:true})}catch(e){report.desktop.errors=[String(e)];try{await dp.screenshot({path:`${out}/desktop-error.png`,fullPage:true})}catch{}}await dctx.close();
const mctx=await browser.newContext({viewport:{width:390,height:844}}),mp=await mctx.newPage();
try{report.mobile.http=await nav(mp,target());await waitReady(mp);report.mobile.data=await inspect(mp);report.mobile.toggle=await toggle(mp);report.mobile.errors=errs(report.mobile.data,report.mobile.toggle,true);await mp.screenshot({path:`${out}/mobile.png`,fullPage:true})}catch(e){report.mobile.errors=[String(e)];try{await mp.screenshot({path:`${out}/mobile-error.png`,fullPage:true})}catch{}}await mctx.close();
await browser.close();
report.pass=!report.desktop.errors?.length&&!report.mobile.errors?.length;
await fs.writeFile(`${out}/report.json`,JSON.stringify(report,null,2));
console.log(JSON.stringify({name:NAME,pass:report.pass,desktop:report.desktop.errors||[],mobile:report.mobile.errors||[]},null,2));
if(!report.pass)process.exitCode=1;
